SELECT $this
WHERE {
    $this nltl:upperIceWaterlineDisplacement ?result .
    ?result qudt:numericValue ?resultValue ;
            qudt:unit <http://qudt.org/vocab/unit/KiloTON_Metric> .
    FILTER (
        NOT EXISTS {
            $this nltl:hasUpperIceWaterlineCase ?case .
            ?case nltl:waterlineCaseDisplacement ?caseQuantity .
            ?caseQuantity qudt:numericValue ?caseValue ;
                          qudt:unit <http://qudt.org/vocab/unit/KiloTON_Metric> .
            FILTER (?caseValue = ?resultValue)
        }
        ||
        EXISTS {
            $this nltl:hasUpperIceWaterlineCase ?greaterCase .
            ?greaterCase nltl:waterlineCaseDisplacement ?greaterQuantity .
            ?greaterQuantity qudt:numericValue ?greaterValue ;
                             qudt:unit <http://qudt.org/vocab/unit/KiloTON_Metric> .
            FILTER (?greaterValue > ?resultValue)
        }
    )
}

PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    {
        $this qudt:numericValue ?value .
        FILTER (?value != "7"^^xsd:decimal)
    }
    UNION
    {
        $this qudt:unit ?unitValue .
        FILTER (?unitValue != unit:DEG)
    }
}

SELECT $this
WHERE {
    $this nltl:designIceCondition
        nltl:mediumFirstYearIceWithPossibleOldIceInclusions .
    FILTER NOT EXISTS {
        $this nltl:shipCategory
            nltl:polarShipCategoryA .
    }
}

SELECT $this
WHERE {
    $this nltl:designIceCondition
        nltl:mediumFirstYearIceWithPossibleOldIceInclusions .
    FILTER NOT EXISTS {
        $this nltl:shipCategory
            nltl:polarShipCategoryA .
    }
}

SELECT $this
WHERE {
    $this <https://w3id.org/nltl/vocab#designIceCondition>
          <https://w3id.org/nltl/vocab#mediumFirstYearIceWithPossibleOldIceInclusions> .
    {
        FILTER NOT EXISTS {
            $this <https://w3id.org/nltl/vocab#shipCategory>
                  <https://w3id.org/nltl/vocab#polarShipCategoryA> .
        }
    }
    UNION
    {
        $this <https://w3id.org/nltl/vocab#shipCategory> ?category .
        FILTER (
            ?category !=
            <https://w3id.org/nltl/vocab#polarShipCategoryA>
        )
    }
}

SELECT $this
WHERE {
    $this <https://w3id.org/nltl/vocab#designIceCondition>
          <https://w3id.org/nltl/vocab#mediumFirstYearIceWithPossibleOldIceInclusions> .
    {
        FILTER NOT EXISTS {
            $this <https://w3id.org/nltl/vocab#shipCategory>
                  <https://w3id.org/nltl/vocab#polarShipCategoryA> .
        }
    }
    UNION
    {
        $this <https://w3id.org/nltl/vocab#shipCategory> ?category .
        FILTER (
            ?category !=
            <https://w3id.org/nltl/vocab#polarShipCategoryA>
        )
    }
}
